"""Render the single consolidated Stage 12 report from completed diagnostics."""
import json
from pathlib import Path
R=Path(__file__).resolve().parents[1]/'reports'
def read(name): return json.loads((R/('stage12_'+name+'.json')).read_text(encoding='utf-8'))
def fmt(v):
    if v is None: return 'not available'
    if isinstance(v,bool): return str(v)
    if isinstance(v,float): return f'{v:.4f}'
    if isinstance(v,(list,dict)): return json.dumps(v,ensure_ascii=False)
    return str(v)
def table(head,rows):
    return '\n\n| '+' | '.join(head)+' |\n| '+' | '.join(['---']*len(head))+' |\n'+'\n'.join('| '+' | '.join(fmt(c).replace('|',' / ') for c in row)+' |' for row in rows)+'\n\n'
K=['macro_f1','suspicious_precision','suspicious_recall','suspicious_f1','average_precision','roc_auc','false_positive_rate']
H=['Macro F1','Precision 1','Recall 1','F1 1','AP','ROC-AUC','FPR']

def main():
    plan=read('plan'); ref=read('reference_reproduction'); a=read('ablation_results'); dep=read('feature_dependence'); small=read('small_feature_models')
    missing=read('missingness_audit'); novelty=read('agent_novelty_shift'); stable=read('stability'); n3=read('n3_diagnosis'); a4=read('a4_diagnosis')
    hard=read('hard_negative_analysis'); comp=read('comparator_robustness'); protection=read('protection'); checkpoint=read('fit_checkpoint'); extra=read('error_details')
    assert checkpoint['status']=='complete' and protection['result']=='PASS'
    decision='B — STRONG BUT FEATURE-CONCENTRATED'
    s=['# MODEL V3 — STAGE 12 CONTROLLED ROBUSTNESS, FEATURE-DEPENDENCE AND WEAK-FAMILY DIAGNOSIS\n',
       '**Technical execution: PASS. Quality decision: '+decision+'.**\n',
       'The Stage 11 reference is reproduced exactly. Removing `agent_wallet_growth_ratio_7d` reduces Validation Macro F1 from **0.9521 to 0.8102** and suspicious recall from **0.9349 to 0.6162**. This is **EXTREME** dependence under the rule frozen before fitting. The missingness-only diagnostic is substantially weaker (Macro F1 **0.5372**, ROC-AUC **0.6828**); missingness alone does not reproduce the reference result. Domain-only positives provide evidence of useful signals in all three domains, but the strong aggregate score depends heavily on the growth feature.\n',
       'This is the single consolidated main report. All new models are diagnostic artifacts, with no promotion or change to the official 32-feature contract. Threshold stays **0.50** throughout. Further controlled development is needed before final model or threshold work.\n',
       '## 1. Scope, preregistration and frozen reference\n',
       'Model inputs were only the corrected Stage 10A Train (60,000 × 32) and Validation (15,000 × 32) matrices. Targets remain 39,781/20,219 and 9,945/5,055 for classes 0/1. The saved Stage 11 model and score hashes were checked before loading. The reference object/file was never refitted or overwritten.\n',
       'Frozen development ground truth and episode plans were joined by transaction ID solely for the requested diagnostic slices. Only transaction type/channel were retained from development transactions for error analysis; no histories or features were recomputed. Metadata never entered fit or predict. No evaluation directory was enumerated or evaluation data opened. Named public certificates were hashed by explicit path.\n']
    s.append(table(['Property','Recorded value'],[['Plan saved UTC',plan['saved_at_utc']],['First diagnostic fit UTC',min(v['started_at_utc'] for v in checkpoint['fits'].values())],['New diagnostic fits',checkpoint['fit_count']],['Wall seconds',checkpoint['wall_seconds']],['Threshold',.5],['Positive / negative fit weight','1.5 / 1; missingness-only uses unit weights'],['Predetermined seeds',stable['seeds']],['Runtime',plan['environment']]]))
    s.append('The plan fixes all feature subsets, the Stage 11 importance ranking, the five seeds, the missingness model and classification rules before the first fit. Nine removal/domain fits, four tiny-feature fits, one missingness fit, five seed fits and one same-seed repeat total **20** new fits. A reuses the saved full reference. All subset models use the same HGB parameters as the reference (200 iterations, learning rate .07, depth 6, 31 leaves, minimum leaf 20, L2=1, no early stopping) and raw marker-preserving inputs. No fitted preprocessing or extra search was introduced. Full estimator defaults and source digests are in the plan.\n')
    s.append(table(['Partition','Max score difference','Predictions identical'],[[p,v['maximum_absolute_difference'],v['predictions_identical']] for p,v in ref['replay'].items()]))
    s.append(table(['Partition']+H+['Confusion [[TN,FP],[FN,TP]]'],[[p]+[ref['metrics_and_slices'][p][k] for k in K]+[ref['metrics_and_slices'][p]['confusion_matrix']] for p in ('train','validation')]))
    s.append('All reproduced domain, family and target-0 hard-negative counts/recalls/FPRs agree with the saved Stage 11 records. Scores use continuous probabilities for AP/ROC-AUC; classification uses probability ≥0.50. AP is Average Precision. Class 1 is the frozen suspicious-pattern review target, not proven criminal activity.\n')
    s.append('## 2. Controlled ablations\n')
    labels={'A':'Saved all-32 reference','B':'Remove growth','C':'Remove growth + novelty','D':'Remove agent domain','E':'Remove network domain','F':'Remove structuring domain','G':'Structuring only','H':'Network only','I':'Agent only','J':'Remove coverage; retain current + behaviour'}
    s.append(table(['Ablation','Representation','Columns'],[[k,labels[k],len(v['columns'])] for k,v in a.items()]))
    for part in ('train','validation'):
        s.append('### '+part.title()+'\n'); s.append(table(['Ablation']+H,[[k]+[v[part][metric] for metric in K] for k,v in a.items()]))
    s.append('### Validation domains and all families\n')
    s.append(table(['Ablation','Domain','Support','TP','FN','Recall'],[[k,d,v['support'],v['tp'],v['fn'],v['recall']] for k,row in a.items() for d,v in row['domains'].items()]))
    s.append(table(['Ablation','Family','Support','TP','FN','Recall'],[[k,d,v['support'],v['tp'],v['fn'],v['recall']] for k,row in a.items() for d,v in row['families'].items()]))
    s.append('### Validation normal false positives\n\nDenominators include target 0 only. Legitimate-origin target 1 is not a false positive under the frozen experiment. Families/domains can overlap; normal categories below are disjoint.\n')
    s.append(table(['Ablation','Category','Support','FP','TN','FPR'],[[k,d,v['support'],v['fp'],v['tn'],v['false_positive_rate']] for k,row in a.items() for d,v in row['normal_fpr'].items()]))
    s.append('## 3. Quantified feature dependence\n\n'+plan['dependence_rule']+'\n\nThese thresholds were saved before fitting and were not revised after results. They measure performance sensitivity to retraining with a feature removed, not causal importance. A correlated substitute or a change in optimization can affect the result.\n')
    b=dep['growth_removed_B']
    s.append(table(['Removal','Index','Classification'],[[k,v['dependence_index'],v['classification']] for k,v in dep['all_ablations'].items()]))
    s.append(table(['Growth-removal metric','B minus A'],[[k,v] for k,v in b['metric_deltas'].items()]))
    for title,key in [('Domain recall','domain_deltas'),('Family recall','family_deltas'),('Normal FPR','normal_fpr_deltas')]:
        s.append(table([title,'B minus A'],[[k,v] for k,v in b[key].items()]))
    s.append('The single-feature removal index is driven by the **0.3187 recall loss**. Removing the whole agent domain is still more damaging. Removing network features also hurts, while removing coverage alone has a much smaller aggregate effect. C has similar Macro F1 to B but a different recall/FPR tradeoff; removing an additional correlated feature need not monotonically worsen every metric. Neither result changes the frozen feature set.\n')
    s.append('## 4. Agent novelty distribution shift\n\nSummaries exclude -1. Missing and available fractions use all rows in each slice.\n')
    s.append(table(['Partition','Slice','N','Available','Missing rate','Mean','Median','SD','Q05','Q25','Q75','Q95'],[[p,k,v['support'],v['available_count'],v['missing_rate']]+[v.get(z) for z in ('mean','median','std','q05','q25','q75','q95')] for p,t in novelty['statistics'].items() for k,v in t.items()]))
    s.append(table(['Disjoint standardization','Composition','Within stratum','Unmatched strata','Total observed mean shift'],[[k,v['composition_effect'],v['within_stratum_effect'],v['unmatched_strata_effect'],v['total_observed_mean_shift']] for k,v in novelty['decompositions'].items()]))
    s.append('The observed novelty shift remains after class and disjoint origin/scenario/target composition standardization. Available-only weights are used, so this decomposition does not mix sentinels with measurements. Family slices A1/A2 overlap and are not summed. Similar overall missing rates cannot explain the large observed-value shift; the displayed within-slice comparisons support a broad partition difference in observed novelty, with smaller composition/availability contributions. This does not identify the generator mechanism or establish future-population transportability. The two-feature removal C gives a bounded sensitivity check, not a novelty-only causal estimate.\n')
    s.append('## 5. Missingness audit\n\nEleven indicator columns are derived only from documented markers: -1 for nonnegative unavailable quantities, -3 for signed changes. Valid -1 cash skews and changes remain observed. These diagnostic indicators never enter the official representation.\n')
    for part,columns in missing['feature_missingness'].items():
        s.append('### '+part.title()+' missingness\n')
        slices=['overall','target_0','target_1','structuring','network','agent','routine']+[f'H{i}' for i in range(1,9)]
        s.append(table(['Feature','Marker','Missing count (all)']+[z+' rate' for z in slices],[[n,v['marker'],v['slices']['overall']['missing_count']]+[v['slices'][z]['missing_rate'] for z in slices] for n,v in columns.items()]))
    s.append('Every slice support, missing count and available count is retained in `stage12_missingness_audit.json`; the rate tables do not hide zero-support slices.\n')
    s.append(table(['Model','Partition']+H,[['Missingness only',p]+[missing['diagnostic_model'][p][k] for k in K] for p in ('train','validation')]))
    s.append(plan['missingness_shortcut_rule']+' The observed flag is **'+missing['shortcut_signal'].upper()+'**. The model is a small unweighted HGB (100 iterations, depth 3, seven leaves, minimum leaf 30, L2=2). Its above-chance ranking shows some coverage association, but it cannot reproduce the reference. This finite diagnostic does not rule out nonlinear interactions between missingness and observed values, nor every generator shortcut.\n')
    s.append('## 6. Univariate and tiny-feature diagnostics\n\nRanking is frozen Stage 11 absolute permutation-AP importance; Stage 12 results did not choose the subsets. The first five are:\n')
    s.append('\n'.join(f'{i}. `{n}`' for i,n in enumerate(small['ranking'][:5],1))+'\n')
    s.append(table(['Top N','Partition']+H,[[n,p]+[v[p][k] for k in K] for n,v in small['models'].items() for p in ('train','validation')]))
    requested=['agent_wallet_growth_ratio_7d','agent_new_wallet_share_7d','agent_top2_count_share_24h','agent_top2_share_change_24h','current_return_path_length','wallet_observed_onward_funding_share_24h','wallet_count_1h_inclusive','wallet_value_24h_inclusive']
    s.append('Raw AUC uses increasing values without choosing a sign. Observed AUC excludes the documented marker; encoded AUC includes it. A low raw AUC can coexist with useful nonmonotonic association. Range overlap cannot rule out a near separator.\n')
    for p,columns in small['univariate']['partitions'].items():
        s.append('### '+p.title()+' univariate diagnostics\n')
        s.append(table(['Feature','Observed AUC','Encoded AUC','Available N','Observed range overlap'],[[n,columns[n]['observed_auc_increasing_value'],columns[n]['encoded_auc_increasing_value'],columns[n]['available_support'],columns[n]['observed_range_overlap']] for n in requested]))
        s.append(table(['Feature','Target','N','Missing rate','Min','Q05','Median','Mean','SD','Q95','Max'],[[n,target,v['support'],v['missing_rate']]+[v.get(k) for k in ('min','q05','median','mean','std','q95','max')] for n in requested for target,v in columns[n]['target_distributions'].items()]))
    s.append('All 32 univariate columns and full distributions are retained in JSON. Growth alone produces substantial discrimination but falls well short of the full reference; top five also fall short. The additional features contribute materially. This is evidence of concentration plus complementary signal, not proof that each domain mechanism is independently recognized.\n')
    s.append('## 7. Domain-only versus overlapping positives\n\nOnly means no family from either other domain; multiple families within the same domain are allowed. Overlap means at least one other domain is active. These are label-evidence slices, not private campaign membership. Low-support flag is N<30.\n')
    s.append(table(['Ablation','Slice','Support','TP','FN','Recall','Low support'],[[k,d,v['support'],v['tp'],v['fn'],v['recall'],v['low_support']] for k,row in read('domain_independence').items() for d,v in row.items()]))
    s.append('The reference recalls are **210/215 structuring-only**, **670/738 network-only**, and **2867/3123 agent-only**. Each overlap slice has recall 1.0. Thus aggregate domain recall benefits from overlap, but the reference also detects many positives unique to every domain. These supports are sufficient for descriptive comparisons under the declared rule; they do not establish independent causal signals or real-world effectiveness. Ablations show where cross-domain proxies can persist even after a domain is removed.\n')
    s.append('The domain-removal contrast is particularly informative: network-only recall falls from **0.9079 to 0.2683** without network features, structuring-only from **0.9767 to 0.4744** without structuring features, and agent-only from **0.9180 to 0.1784** without agent features. Removing growth alone reduces agent-only recall to **0.4019**, while network-only and structuring-only recall remain above 0.91 and 0.98 respectively. Aggregate overlap recall masks much of these domain-specific losses.\n')
    for code,d in [('N3',n3),('A4',a4)]:
        s.append('## '+('8. N3 reciprocal cycle diagnosis' if code=='N3' else '9. A4 cash imbalance diagnosis')+'\n')
        s.append(f"Reference support **{d['support']}**, TP **{d['tp']}**, FN **{d['fn']}**. TP/FN comparisons are observational diagnostics at the unchanged threshold.\n")
        fc=d['feature_comparison']
        s.append(table(['Feature','Group','Available N','Missing rate','Mean','Median','SD','Q05','Q95'],[[n,label,v['available_count'],v['missing_rate']]+[v.get(z) for z in ('mean','median','std','q05','q95')] for n in d['recommended_feature_views'] for label,v in [('TP',fc['first_group'][n]),('FN',fc['second_group'][n])]]))
        s.append(table(['Family overlap','Support','TP','FN','Recall'],[[k,v['support'],v['tp'],v['fn'],v['recall']] for k,v in d['family_overlap'].items()]))
        s.append(table(['Domain membership','Support','TP','FN','Recall'],[[k,v['support'],v['tp'],v['fn'],v['recall']] for k,v in d['domain_overlap'].items() if v['support']]))
        for field in ('strength','recipe','transaction_type','diagnosed_family_onset_position'):
            s.append(table([field,'Support','TP','FN','Recall'],[[k,v['support'],v['predicted_positive'],v['predicted_negative'],v['positive_prediction_rate']] for k,v in d['metadata_categories'][field].items()]))
        s.append('Strength and recipe describe private generation provenance, not a measured causal signal. Missing provenance stays “not recorded.” Onset offsets are episode event positions relative to the recorded own-family onset and are applicable only when the private scenario family matches the diagnosed family. They are not time delays or universal cross-family onset. Per-row diagnostic values and all metadata categories are retained in JSON.\n')
        if code=='N3':
            s.append(table(['Selected path length','Support','TP','FN','Recall'],[[k,v['support'],v['tp'],v['fn'],v['recall']] for k,v in d['path_length_strata'].items()]))
            s.append(table(['Coverage below 28d','Support','TP','FN','Recall'],[[k,v['support'],v['tp'],v['fn'],v['recall']] for k,v in d['cold_history'].items()]))
            s.append('**Diagnosis:** all 41 positives have a nonzero selected path. Fifteen of 19 misses are one-edge paths; longer paths have lower observed recall, but only five examples have length two or three. Median return ratio is **0.5577 for TP versus 0.9469 for FN**. Two misses have selected ratios outside [0.25,1.25], versus none of the TPs; a selected topological path is a lossy summary and need not be the path used by the frozen predicate. This observation is consistent with compression limits, not proof of an incorrect label.\n\nAll 19 misses belong to network-only positives; all six cross-domain overlaps are detected. Only four misses have wallet coverage below 28 days, so cold history does not explain most misses. FN mean outflow count is 1.5263 versus 2.3636 for TP, whereas receiver counts are similar. FN current-amount median is $125.49 versus $92.695; extreme values make means less informative. Misses occur across recipes (five in N3, eight without a recorded recipe, six elsewhere), so no single recipe explains them. Only two examples have private weak strength and only six support a diagnosed-family onset offset: these slices are too small for stable strength/onset conclusions. Shared comparator weakness and the small Train/Validation family support motivate representation/support investigation; this stage neither proves sufficiency nor adds an oracle feature.\n')
        else:
            s.append(table(['Slice','Support','TP','FN','Recall'],[[k,v['support'],v['tp'],v['fn'],v['recall']] for k,v in {**d['baseline_availability'],'other A1/A2/A3 overlap':d['other_agent_overlap'],'no other agent family':d['no_other_agent_family']}.items()]))
            similarity=d['hard_H8_similarity']
            s.append(table(['Feature','A4 FN observed mean','H8 target-0 observed mean','A4 FN minus H8 standardized mean'],[[n,similarity['first_group'][n].get('mean'),similarity['second_group'][n].get('mean'),similarity['contrasts'][n]['standardized_mean_difference']] for n in d['recommended_feature_views']]))
            s.append(table(['Group','Absolute quantity','Observed N','Mean magnitude','Median magnitude'],[[group,n,v['available_count'],v.get('mean'),v.get('median')] for group,columns in extra['A4_absolute_skews'].items() for n,v in columns.items()]))
            s.append('**Diagnosis:** weak cash magnitude and cold displayed history do not explain most misses. All A4 rows have agent coverage capped at 28 days; **87/88 misses have an available skew-change baseline**. Mean absolute value/count skew is **0.9627/0.7722 for FN**, compared with **0.9388/0.6922 for TP**. Signed averages mix opposite cash directions and would conceal this. Mean absolute observed change is 0.9331 for FN versus 0.9613 for TP.\n\nCo-occurring agent evidence is strongly associated with detection: **148/156 (0.9487)** with A1/A2/A3 overlap versus **101/181 (0.5580)** without it. FN observed growth averages 1.0434 versus 1.4454 for TP, and service counts are lower. Most misses therefore occur where the model has less support from other agent behaviours despite substantial cash imbalance. H8 target-0 absolute-skew ranges overlap the misses, but their average absolute value/count skews are much lower (0.5355/0.3195); similarity of individual cash quantities does not establish equivalence of the full reference conditions. Weak private strength has only six examples and onset offsets only twelve, so those comparisons are inconclusive. Weighting/model tradeoffs and omitted joint cash-service information remain plausible explanations; they cannot be separated causally by these diagnostics.\n')
    s.append('## 10. Sparse families\n')
    s.append(table(['Partition','Family','Positive support','TP','FN','Observed recall'],[[p,k,v['support'],v['tp'],v['fn'],v['recall']] for p,rows in comp['sparse_family_support_and_reference_recall'].items() for k,v in rows.items()]))
    s.append('Train S2 has four positives and Validation one; S4 has 40 and eight. One changed Validation prediction changes S2 recall by 100 percentage points and S4 by 12.5 points. Their observed recalls cannot establish reliable generalization. No split changes, sparse-case tuning or additional evaluation examples were used. Dependence among events further limits naive independent-row uncertainty claims.\n')
    s.append('## 11. H1 and H5 false positives\n\nWithin each target-0 category, first group is FP and second is TN. All 32 distributions and missing-rate differences are retained in JSON. The tables rank the eight largest absolute observed standardized mean differences using pooled population SD. They are descriptive and sensitive to outliers/correlation; no feature was changed.\n')
    for code,d in hard.items():
        s.append('### '+code+'\n'); s.append(table(['Support','FP','TN','FPR'],[[d['counts'][k] for k in ('support','fp','tn','false_positive_rate')]]))
        fc=d['fp_vs_tn']; ranked=fc['features_ranked_by_absolute_standardized_mean_difference'][:8]
        s.append(table(['Feature','FP observed N','TN observed N','FP mean','TN mean','FP median','TN median','Standardized mean difference','Missing rate difference'],[[n,fc['first_group'][n]['available_count'],fc['second_group'][n]['available_count'],fc['first_group'][n].get('mean'),fc['second_group'][n].get('mean'),fc['first_group'][n].get('median'),fc['second_group'][n].get('median'),fc['contrasts'][n]['standardized_mean_difference'],fc['contrasts'][n]['missing_rate_difference']] for n in ranked]))
        for field in ('recipe','transaction_type','channel'):
            s.append(table([field,'Target-0 support','FP','TN','FPR'],[[k,v['support'],v['predicted_positive'],v['predicted_negative'],v['positive_prediction_rate']] for k,v in d['categories'][field].items()]))
        if code=='H1':
            s.append('H1 errors are associated with higher observed wallet/agent acceleration, more endpoint coverage and greater sender breadth. W2W has 29/102 false positives (0.2843), versus 2/63 Cash-In and 8/73 Cash-Out. Direct-channel FPR is 16/54 (0.2963), but type/channel are correlated diagnostic slices, not causal effects. S1 and S3 recipes both contribute (21/133 and 18/105). The high-ranked return-ratio contrast has only **three FP and one TN observed values**, so it is not reliable evidence of a systematic driver.\n')
        else:
            s.append('H5 errors concentrate in the N4 transit recipe: **18/114**, compared with **3/100** N2 payroll/dispersion. Higher sender breadth/outflow counts and day/hour activity distinguish FP from TN. The leading observed top-two-change contrast has only **two available FP values** and sender acceleration only four, so robust inference from those rankings is unwarranted. Their missing-rate differences are reported separately. Endpoint coverage/current amount and all feature domains are retained in the full JSON comparisons; no one-feature cause is established.\n')
    s.append('## 12. Seed sensitivity and repeated-fit reproducibility\n\nExactly five predetermined seeds were tested, plus one separately declared same-seed repeat. The saved Stage 11 reference was reused for comparison and never refitted.\n')
    s.append(table(['Run']+H+['Structuring recall','Network recall','Agent recall'],[[v['name']]+[v['validation'][k] for k in K]+[v['domains'][k]['recall'] for k in ('structuring','network','agent')] for v in stable['runs']+[stable['same_seed_repeat']]]))
    s.append(table(['Metric','Mean','SD','Min','Max'],[[k,v['mean'],v['std'],v['min'],v['max']] for k,v in {**stable['validation_metric_summary'],**{d+' recall':v for d,v in stable['domain_summary'].items()}}.items()]))
    s.append(table(['Run','Maximum probability difference versus saved reference'],[[k,v] for k,v in stable['max_score_difference_from_saved_reference'].items()]))
    s.append('All five seed runs and the same-seed repeat produce identical probabilities on this data. With no early stopping and all features available at each split, the configuration exhibits no seed sensitivity here. These fits establish same-environment reproducibility, not five independent estimates of population robustness. No seed was selected.\n')
    s.append('## 13. Existing comparator robustness\n\nAll comparator scores are reused from hashed Stage 11 artifacts. No comparator was retrained.\n')
    s.append(table(['Candidate']+H,[[name]+[v['validation'][k] for k in K] for name,v in comp['models'].items()]))
    for title,key,rate in [('Domains','domains','recall'),('Families','families','recall'),('Normal categories','normal_fpr','false_positive_rate')]:
        s.append('### '+title+'\n'); names=list(comp['models']); first=comp['models'][names[0]][key]
        s.append(table(['Slice','Support']+names,[[k,v['support']]+[comp['models'][name][key][k][rate] for name in names] for k,v in first.items()]))
    s.append('N3 is weak across the four models (recall 0.2927–0.5610), while A4 ranges 0.5045–0.7389. H1 remains a high-FPR category across them; H5 also remains difficult and differs by model. Shared difficulties support a representation/data-support concern in addition to model-specific tradeoffs, but do not prove that another representation would fix them.\n')
    s.append('## 14. Decision and next boundary\n\n**'+decision+'.**\n\nThe preregistered single-growth removal is EXTREME, removal of the whole agent domain is highly damaging, and tiny subsets recover substantial but incomplete performance. This outweighs the unchanged high full-model score as evidence for unconditional robustness approval. At the same time, strong domain-only recall and the weak missingness-only model show that the result is not explained solely by overlapping agent labels or unavailable markers.\n\nNovelty has a material within-partition distribution difference that warrants further controlled investigation. N3 and A4 remain family-specific weaknesses; S2/S4 support is inadequate for reliable generalization claims. Another separately authorized controlled-development stage should examine growth dependence, novelty transportability and the specific weak-family representation gaps before final model/threshold development. No feature proposal is promoted by this stage.\n\nValidation has now been reused for model selection and diagnostics. These are selected synthetic development results; neither causal feature independence nor real-world AML performance follows. Frozen target semantics remain the authority for these measurements; this stage does not certify every reference-evaluator implementation detail against the original written predicates.\n')
    s.append('## 15. Protection, evidence and reproducibility\n')
    s.append(table(['Protection property','Result'],[['Before files',len(protection['before']['files'])],['After files',len(protection['after']['files'])],['Changed paths',protection['changed']],['Public commitment unchanged',protection['public_commitment_unchanged']]]))
    s.append(table(['Named public certificate','Before SHA-256','After SHA-256'],[[p,d,protection['after']['public'][p]] for p,d in protection['before']['public'].items()]))
    s.append('The explicit allowlist covers application/V1/V2 paths, frozen V3 development inputs/design, Stage 10A contract/matrices/code/evidence, earlier artifacts and all Stage 11 candidates/scores/code/reports. Exact paths and exclusions are in the protection record. No dataset root or evaluation subtree is recursively inventoried. This verifies public commitment metadata and the listed development artifacts; it does not freshly verify unread evaluation bytes.\n\nThree regression tests passed: column-specific marker statistics, preregistered dependence cutoffs, and overlap/count orientation including the exact 0.50 tie. The independent final verification recomputes every saved diagnostic metric/slice, checks artifact/input/source hashes, and rechecks protected files. See `stage12_final_verification.json`.\n')
    names=['plan','reference_reproduction','ablation_results','feature_dependence','agent_novelty_shift','missingness_audit','small_feature_models','domain_independence','n3_diagnosis','a4_diagnosis','error_details','hard_negative_analysis','stability','comparator_robustness','protection','fit_checkpoint','artifact_manifest','final_verification']
    s.append(table(['Evidence','File'],[[n,f'[stage12_{n}.json](stage12_{n}.json)'] for n in names]))
    s.append('Entry points from the repository root:\n\n```powershell\npython -B -m unittest discover -s ml_v3/tests -p test_stage12_robustness.py -v\npython -B ml_v3/src/run_stage12.py\npython -B ml_v3/src/verify_stage12.py\npython -B ml_v3/src/report_stage12.py\n```\n\nThe runner refuses existing Stage 12 outputs. For a fresh reproduction, preserve this evidence and use an isolated development checkout with the same frozen sources/environment and a newly captured protection-before record. Do not delete prior evidence to rerun. Reports render completed diagnostics only. New joblib files and score arrays live under `models/stage12_diagnostics/` and are labelled diagnostic only.\n\nNo threshold optimization, calibration, feature promotion, final model declaration, Train+Validation refit or application integration occurred.\n\n**V3 STAGE 12 COMPLETE — WAITING FOR APPROVAL.**\n')
    (R/'V3_STAGE12_ROBUSTNESS_REPORT.md').write_text('\n'.join(s),encoding='utf-8',newline='\n')

if __name__=='__main__': main()
